import React, { useEffect, useMemo, useRef, useState } from 'react';

type Role = 'user' | 'assistant';

type Message = {
    id: string;
    role: Role;
    text: string;
};

type Rule = {
    id: string;
    keywords: string[];
    responses: string[];
};

const rules: Rule[] = [
    {
        id: 'intro',
        keywords: [
            'who',
            'who are you',
            'who is the artist',
            'who is the fashion design',
            'about',
            'about the artist',
            'introduction',
            'what do you stand for',
            'message',
            'mission'
        ],
        responses: [
            "I'm Arin, a designer who fuses fashion, research, and textiles to ask how bodies and technologies co-shape each other.",
            "Think of me as a bridge between craft and critical theory: I prototype garments, write about posthuman fashion, and stitch ideas into fabric.",
            "Curious? I'm the designer behind these projects—invested in how clothing can question power, identity, and futurity."
        ]
    },
    {
        id: 'research',
        keywords: [
            'academic',
            'research',
            'posthumanism',
            'post human',
            'ai',
            'artificial intelligence',
            'capitalism',
            'fashion and capitalism',
            'literature',
            'papers',
            'paper',
            'essay',
            'publication'
        ],
        responses: [
            "My research spans posthumanism, AI in fashion, and critiques of capitalism. I can show you a reading list and my papers—want to open the research section?",
            "I write about garments as interfaces: posthuman fashion, AI-mediated authorship, and fashion under capital. Ask for papers and I'll surface the list.",
            "Academic hat on: I've published on AI x fashion, posthuman bodies, and literature on capital. Say 'show research' to view the papers."
        ]
    },
    {
        id: 'contact',
        keywords: [
            'contact',
            'collaboration',
            'collaborate',
            'reach out',
            'email',
            'ask',
            'talk to you',
            'hire',
            'commission'
        ],
        responses: [
            "I'd love to connect. Drop a note in the contact form and tell me what you're envisioning—I'll reply soon.",
            "Collaboration sounds great. Want me to open the contact form so you can share details?",
            "Ready to reach out? I can route you to the contact section to share your idea or request."
        ]
    },
    {
        id: 'textile',
        keywords: [
            'textile',
            'textiles',
            'textile design',
            'textile creation',
            'embroidery',
            'embrodiery',
            'embroider',
            'threads',
            'fabric',
            'weave',
            'loom',
            '3d textile',
            'surface design'
        ],
        responses: [
            "Textile lab is open: hand embroidery, layered threads, and 3D textile experiments. Want to see the textile projects?",
            "I translate visuals into stitch and weave. I can show you embroidery-driven pieces and textured textiles—shall we?",
            "Surface stories: threads, fabric manipulations, and bespoke textiles. Ask for textiles to pull up the gallery."
        ]
    },
    {
        id: 'conversation',
        keywords: [
            'conversation',
            "let's talk",
            'lets talk',
            'what are your thoughts',
            'discuss',
            'chat',
            'debate',
            'talk about',
            'curious about your take'
        ],
        responses: [
            "Happy to dive in—pick a thread: AI in fashion, literature, or how garments shape identity?",
            "I can riff with you. What angle intrigues you—ethics of AI design, posthuman bodies, or craft futures?",
            "Let's explore together. Name a topic and I'll respond in the way I think about my practice."
        ]
    },
    {
        id: 'fashion',
        keywords: [
            'fashion projects',
            'fashion design',
            'outfits',
            'atelier',
            'atellier',
            'silhouettes',
            'graduation project',
            'show outfits',
            'performance outfits',
            'theatre outfits',
            'costume',
            'wardrobe'
        ],
        responses: [
            "I'll pull looks from my fashion archive—silhouettes, performance pieces, and show outfits. Want to view the projects grid?",
            "From runway to theatre, I design outfits with narrative silhouettes. Say 'show fashion' to see examples.",
            "I can reveal fashion projects: graduation work, performance looks, and atelier pieces. Shall I bring them up?"
        ]
    },
    {
        id: 'placeholder',
        keywords: ['placeholder', 'future slot', 'seventh path', 'extra path'],
        responses: [
            "You've unlocked the seventh slot—a reserved lane for new ideas. Tell me what you'd like added here.",
            "This is a placeholder trajectory. Describe the behavior you want and I'll note it for the next iteration."
        ]
    }
];

const miscSmallTalk = [
    "I'm here—ask me about the work, the research, or the stitches between.",
    "Not sure where to start? Try 'who are you' or 'show research'.",
    "I can guide you: projects, research, textiles, fashion, or reach out to collaborate."
];

const conversationFallback = rules.find((rule) => rule.id === 'conversation')?.responses ?? [];

const pickOne = (items: string[]) => items[Math.floor(Math.random() * items.length)];

const findRule = (input: string): Rule | undefined => {
    const normalized = input.toLowerCase();
    return rules.find((rule) => rule.keywords.some((keyword) => normalized.includes(keyword)));
};

const createId = () => `${Date.now()}-${Math.random().toString(16).slice(2)}`;

const Chatbox: React.FC = () => {
    const [input, setInput] = useState('');
    const [messages, setMessages] = useState<Message[]>([
        {
            id: 'welcome',
            role: 'assistant',
            text: "Welcome. I'm your studio guide—ask about who I am, research, textiles, fashion projects, or how to collaborate."
        }
    ]);
    const [isTyping, setIsTyping] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement | null>(null);

    const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
        event.preventDefault();
        if (!input.trim() || isTyping) return;

        const userText = input.trim();
        const userMessage: Message = { id: createId(), role: 'user', text: userText };
        const responseText = buildResponse(userText);

        setMessages((prev) => [...prev, userMessage]);
        setInput('');
        setIsTyping(true);

        const delay = 520 + Math.random() * 420;
        window.setTimeout(() => {
            setMessages((prev) => [...prev, { id: createId(), role: 'assistant', text: responseText }]);
            setIsTyping(false);
        }, delay);
    };

    const buildResponse = (userText: string) => {
        const matchedRule = findRule(userText);
        if (matchedRule) {
            return pickOne(matchedRule.responses);
        }
        return pickOne([...conversationFallback, ...miscSmallTalk]);
    };

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages]);

    const placeholderRuleText = useMemo(
        () =>
            pickOne([
                'There is a reserved seventh path ready for any new storyline you want to add—just describe it.',
                'Future lane available. Tell me what should live here and I will adapt next iteration.'
            ]),
        []
    );

    return (
        <div className="chatbox" aria-label="AI assistant chat">
            <div className="chatbox__header">Studio Assistant</div>
            <div className="chatbox__messages">
                {messages.map((msg) => (
                    <div key={msg.id} className={`chatbox__message chatbox__message--${msg.role}`}>
                        <span className="chatbox__bubble">{msg.text}</span>
                    </div>
                ))}
                {isTyping && (
                    <div className="chatbox__message chatbox__message--assistant">
                        <span className="chatbox__bubble chatbox__bubble--typing">
                            <span className="dot" />
                            <span className="dot" />
                            <span className="dot" />
                        </span>
                    </div>
                )}
                <div ref={messagesEndRef} />
            </div>
            <form className="chatbox__input" onSubmit={handleSubmit}>
                <input
                    type="text"
                    value={input}
                    onChange={(event) => setInput(event.target.value)}
                    placeholder="Ask about projects, research, textiles, or start a conversation"
                    aria-label="Chat input"
                    disabled={isTyping}
                />
                <button type="submit" disabled={!input.trim() || isTyping}>
                    Send
                </button>
            </form>
            <div className="chatbox__footer">{placeholderRuleText}</div>
        </div>
    );
};

export default Chatbox;
